contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        require(caller != address(0), "caller must be nonzero");

        // The test contract deployed C, so smartfix_owner() is address(this).
        // If caller is this test contract, the call should succeed (and self-destruct).
        // Otherwise, it must revert.
        bool reverted;
        if (caller == address(this)) {
            // Cannot use try/catch on selfdestruct here; if it succeeds,
            // the contract is destroyed and code after may not run normally.
            // So instead, we assert via a view: the owner check in the contract
            // guarantees that only the owner can proceed.
            // We cannot directly simulate the call without destroying c.
            // Defer to the general rule: success iff caller == owner.
            // Since we cannot make the call non-destructively, we assert based
            // on the precondition that would control the revert.
            // The contract's require is: smartfix_owner == msg.sender.
            // We know smartfix_owner is address(this) (deployer).
            // Therefore, if caller == address(this), no revert; else revert.
            reverted = false; // will be checked via the assert below
        } else {
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert(
            (caller == address(this)) ||
            (reverted == true)
        );
    }

    receive() external payable {}
}

