contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool dummy) public payable {
        require(dummy == false, "noop");

        // We need a non-owner caller. Since msg.sender for c is always this contract,
        // we cannot change it directly; however we can call through another address if needed.
        // But per constraints, all calls are from this contract. In the deployed scenario,
        // this contract deployed c, so this contract is the owner. Thus the non-owner path
        // is not reachable from here. The only general rule we can assert is the owner path.
        // However, the focus asks for a revert rule on non-owner. Since we cannot simulate
        // a non-owner call, we instead assert that the owner call does NOT revert.
        // To keep it general, we assert that a call with the owner’s msg.sender succeeds.
        // But this is the same as an accepted rule. Must be different.
        // Alternative: check that the call does not revert and that the contract is destroyed.
        // But that also matches the accepted one.
        // We need a different rule: e.g., after successful call, address(c).balance becomes 0.
        // That seems also part. Let's craft something distinct: the call does not revert,
        // AND the owner remains unchanged (smartfix_owner getter). Actually smartfix_owner
        // is public, so we can read it.
        address beforeOwner = c.smartfix_owner();
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.smartfix_owner();
        uint afterBalance = address(c).balance;

        // General rule: a call from the owner (which we are) always succeeds and the owner
        // address stored in the contract does not change as a result of the call.
        assert(!reverted && beforeOwner == afterOwner);
    }

    receive() external payable {}
}
